using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class PersonTests
{
    // Use Student as a concrete subclass of abstract Person
    private static Student CreatePerson(string lastName, string firstMidName)
    {
        return new Student
        {
            LastName = lastName,
            FirstMidName = firstMidName,
            EnrollmentDate = DateTime.Today
        };
    }

    [Fact]
    public void FullName_ReturnsLastNameCommaFirstName()
    {
        var person = CreatePerson("Doe", "John");

        Assert.Equal("Doe, John", person.FullName);
    }

    [Fact]
    public void FullName_WithMiddleName_IncludesFullFirstMidName()
    {
        var person = CreatePerson("Smith", "Jane Marie");

        Assert.Equal("Smith, Jane Marie", person.FullName);
    }

    [Fact]
    public void FullName_DifferentValues_ProducesDifferentResults()
    {
        var person1 = CreatePerson("Alpha", "Beta");
        var person2 = CreatePerson("Gamma", "Delta");

        Assert.NotEqual(person1.FullName, person2.FullName);
        Assert.Equal("Alpha, Beta", person1.FullName);
        Assert.Equal("Gamma, Delta", person2.FullName);
    }

    [Fact]
    public void FullName_SingleCharNames_FormatsCorrectly()
    {
        var person = CreatePerson("X", "Y");

        Assert.Equal("X, Y", person.FullName);
        Assert.Contains(", ", person.FullName);
    }

    [Fact]
    public void FullName_IsComputedProperty_ReflectsChanges()
    {
        var person = CreatePerson("Original", "Name");
        Assert.Equal("Original, Name", person.FullName);

        person.LastName = "Updated";
        Assert.Equal("Updated, Name", person.FullName);

        person.FirstMidName = "NewFirst";
        Assert.Equal("Updated, NewFirst", person.FullName);
    }
}

