using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests
{
    private static void SeedStudents(SchoolContext context)
    {
        context.Students.AddRange(
            new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = new DateTime(2019, 9, 1) },
            new Student { LastName = "Li", FirstMidName = "Yan", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { LastName = "Justice", FirstMidName = "Peggy", EnrollmentDate = new DateTime(2022, 9, 1) }
        );
        context.SaveChanges();
    }

    // ---- Index tests ----

    [Fact]
    public void Index_NoParameters_ReturnsAllStudents()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index(null, null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(5, model.Count);
        // Default sort is by LastName ascending
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Li", model[3].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByLastName()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index(null, null, "Al", null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
        Assert.All(model, s => Assert.True(
            s.LastName.Contains("Al") || s.FirstMidName.Contains("Al"),
            $"Student {s.FullName} does not match search 'Al'"));
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByFirstName()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act — "Yan" matches FirstMidName of Li, Yan
        var result = controller.Index(null, null, "Yan", null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Li", model[0].LastName);
        Assert.Equal("Yan", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SortByNameDesc_ReturnsSortedStudentsDescending()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index("name_desc", null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(5, model.Count);
        // Descending by LastName: Li, Justice, Barzdukas, Alonso, Alexander
        Assert.Equal("Li", model[0].LastName);
        Assert.Equal("Justice", model[1].LastName);
        Assert.Equal("Alexander", model[4].LastName);
    }

    [Fact]
    public void Index_SortByDate_ReturnsSortedByEnrollmentDateAscending()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index("Date", null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        // Earliest enrollment first: 2019 (Barzdukas), then 2020s, 2021, 2022
        Assert.Equal("Barzdukas", model[0].LastName);
        Assert.Equal("Justice", model[4].LastName);
        Assert.True(model[0].EnrollmentDate <= model[1].EnrollmentDate);
        Assert.True(model[3].EnrollmentDate <= model[4].EnrollmentDate);
    }

    [Fact]
    public void Index_Paging_ReturnsCorrectPage()
    {
        // Arrange — seed 12 students so page 2 (size 10) has 2 items
        using var context = TestDbContextFactory.Create();
        for (int i = 0; i < 12; i++)
        {
            context.Students.Add(new Student
            {
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2020, 1, 1)
            });
        }
        context.SaveChanges();
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index(null, null, null, 2) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
        Assert.Equal(2, model.PageIndex);
        Assert.Equal(2, model.TotalPages);
        Assert.True(model.HasPreviousPage);
        Assert.False(model.HasNextPage);
    }

    [Fact]
    public void Index_SearchAndSort_CombinesFilters()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act — search "Al" with name_desc sort
        var result = controller.Index("name_desc", null, "Al", null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
        // name_desc among matches: Alonso before Alexander? No — desc: Alonso > Alexander
        Assert.Equal("Alonso", model[0].LastName);
        Assert.Equal("Alexander", model[1].LastName);
    }

    [Fact]
    public void Index_SearchString_SetsViewBagCurrentFilter()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index(null, null, "test", null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("test", controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_NewSearch_ResetsPageToOne()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act — searchString is not null so page resets to 1
        var result = controller.Index(null, null, "Al", 3) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    // ---- Details tests ----

    [Fact]
    public void Details_ValidId_ReturnsStudentWithEnrollments()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = new DateTime(2020, 1, 1) };
        context.Students.Add(student);
        context.SaveChanges();
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Details(student.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal("Test", model.LastName);
        Assert.Equal("User", model.FirstMidName);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Details_InvalidId_ThrowsInvalidOperationException()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        using var controller = new StudentsController(context);

        // Act & Assert — .Single() throws when no match
        Assert.Throws<InvalidOperationException>(() => controller.Details(999));
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    // ---- Create tests ----

    [Fact]
    public void Create_GET_ReturnsViewWithStudentHavingTodayDate()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_POST_ValidStudent_RedirectsToIndex()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        using var controller = new StudentsController(context);
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        var result = controller.Create(student);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        // Verify student was persisted
        Assert.Single(context.Students);
        Assert.Equal("NewStudent", context.Students.First().LastName);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsViewWithStudent()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        using var controller = new StudentsController(context);
        controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2023, 9, 1)
