        Assert.Empty(context.Students);
    }

    // ---- Edit tests ----

    [Fact]
    public void Edit_GET_ValidId_ReturnsStudentInView()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        var student = new Student { LastName = "Edit", FirstMidName = "Me", EnrollmentDate = new DateTime(2020, 5, 15) };
        context.Students.Add(student);
