         // Arrange
         using var context = TestDbContextFactory.Create();
         using var controller = new StudentsController(context);

         // Act
         var result = controller.Edit((int?)null);

         // Assert
         var statusResult = Assert.IsType<StatusCodeResult>(result);
         Assert.Equal(400, statusResult.StatusCode);
     }

     [Fact]
     public void Edit_POST_ValidUpdate_RedirectsToIndex()
     {
         // Arrange
         using var context = TestDbContextFactory.Create();
         var student = new Student { LastName = "Before", FirstMidName = "Edit", EnrollmentDate = new DateTime(2020, 1, 1) };
         context.Students.Add(student);
         context.SaveChanges();
         // Detach so the Edit POST can attach modified entity
         context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

         using var controller = new StudentsController(context);
         var updatedStudent = new Student
         {
             ID = student.ID,
             LastName = "After",
             FirstMidName = "Edit",
             EnrollmentDate = new DateTime(2021, 1, 1)
         };

         // Act
         var result = controller.Edit(updatedStudent);

         // Assert
         var redirect = Assert.IsType<RedirectToActionResult>(result);
         Assert.Equal("Index", redirect.ActionName);
         var saved = context.Students.Find(student.ID);
         Assert.Equal("After", saved!.LastName);
         Assert.Equal(new DateTime(2021, 1, 1), saved.EnrollmentDate);
     }

     [Fact]
     public void Edit_POST_InvalidModelState_ReturnsViewWithStudent()
     {
         // Arrange
         using var context = TestDbContextFactory.Create();
         using var controller = new StudentsController(context);
         controller.ModelState.AddModelError("LastName", "Required");
         var student = new Student
         {
             ID = 1,
             FirstMidName = "Test",
             EnrollmentDate = new DateTime(2023, 9, 1)
         };

         // Act
         var result = controller.Edit(student) as ViewResult;

         // Assert
         Assert.NotNull(result);
         Assert.IsType<Student>(result.Model);
     }

     // ---- Delete tests ----

     [Fact]
     public void Delete_GET_ValidId_ReturnsStudentInView()
     {
         // Arrange
         using var context = TestDbContextFactory.Create();
         var student = new Student { LastName = "Delete", FirstMidName = "Me", EnrollmentDate = new DateTime(2020, 1, 1) };
         context.Students.Add(student);
         context.SaveChanges();
         using var controller = new StudentsController(context);

         // Act
         var result = controller.Delete(student.ID) as ViewResult;

         // Assert
         Assert.NotNull(result);
         var model = Assert.IsType<Student>(result.Model);
         Assert.Equal("Delete", model.LastName);
         Assert.Equal(student.ID, model.ID);
     }

     [Fact]
     public void Delete_GET_InvalidId_ReturnsNotFound()
     {
         // Arrange
         using var context = TestDbContextFactory.Create();
         using var controller = new StudentsController(context);

         // Act
         var result = controller.Delete(999);

         // Assert
         Assert.IsType<NotFoundResult>(result);
     }

     [Fact]
     public void Delete_GET_NullId_ReturnsBadRequest()
     {
         // Arrange
         using var context = TestDbContextFactory.Create();
         using var controller = new StudentsController(context);

         // Act
         var result = controller.Delete(null);

         // Assert
         var statusResult = Assert.IsType<StatusCodeResult>(result);
         Assert.Equal(400, statusResult.StatusCode);
     }

     [Fact]
     public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
     {
         // Arrange
         using var context = TestDbContextFactory.Create();
         var student = new Student { LastName = "Remove", FirstMidName = "Me", EnrollmentDate = new DateTime(2020, 1, 1) };
         context.Students.Add(student);
         context.SaveChanges();
         using var controller = new StudentsController(context);

         // Act
         var result = controller.DeleteConfirmed(student.ID);

         // Assert
         var redirect = Assert.IsType<RedirectToActionResult>(result);
         Assert.Equal("Index", redirect.ActionName);
         Assert.Empty(context.Students);
     }

     [Fact]
     public void DeleteConfirmed_InvalidId_ThrowsNullReferenceException()
     {
         // Arrange — Find returns null, then accessing student.FirstMidName throws NRE
         // The catch block tries to use TempData which requires HttpContext, so the exception propagates
         using var context = TestDbContextFactory.Create();
         using var controller = new StudentsController(context);

         // Act & Assert — NullReferenceException from accessing null student's properties
         Assert.ThrowsAny<NullReferenceException>(() => controller.DeleteConfirmed(999));
     }
 }

