using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;
    private readonly CoursesController _controller;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.ContentRootPath).Returns("/fake/path");
        _mockEnv.Setup(e => e.WebRootPath).Returns((string?)null);
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department SeedDepartment(string name = "Engineering", decimal budget = 100000m)
    {
        var instructor = new Instructor
        {
            LastName = "Fakhouri",
            FirstMidName = "Fadi",
            HireDate = new DateTime(2002, 7, 6)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var dept = new Department
        {
            Name = name,
            Budget = budget,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(Department dept, int courseId = 1050, string title = "Chemistry", int credits = 3)
    {
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
    {
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns(fileName);
        mockFile.Setup(f => f.Length).Returns(length);
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Verifiable();
        return mockFile;
    }

    // ---- Index tests ----

    [Fact]
    public void Index_WithCourses_ReturnsViewWithCourseList()
    {
        // Arrange
        var dept = SeedDepartment();
        SeedCourse(dept, 1050, "Chemistry", 3);
        SeedCourse(dept, 2021, "Composition", 3);
        SeedCourse(dept, 3045, "Calculus", 4);

        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.All(model, c => Assert.NotNull(c.Department));
        Assert.All(model, c => Assert.Equal("Engineering", c.Department.Name));
    }

    [Fact]
    public void Index_NoCourses_ReturnsEmptyList()
    {
        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Empty(model);
    }

    // ---- Details tests ----

    [Fact]
    public void Details_ValidId_ReturnsCourseWithDepartment()
    {
        // Arrange
        var dept = SeedDepartment("Mathematics");
        var course = SeedCourse(dept, 4041, "Macroeconomics", 3);

        // Act
        var result = _controller.Details(4041) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(4041, model.CourseID);
        Assert.Equal("Macroeconomics", model.Title);
        Assert.Equal(3, model.Credits);
        Assert.NotNull(model.Department);
        Assert.Equal("Mathematics", model.Department.Name);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ThrowsInvalidOperationException()
    {
        // Act & Assert — .Single() throws when no match found
        Assert.Throws<InvalidOperationException>(() => _controller.Details(9999));
    }

    // ---- Create GET tests ----

    [Fact]
    public void Create_GET_ReturnsViewWithDepartmentSelectList()
    {
        // Arrange
        var dept1 = SeedDepartment("Engineering");
        // Add a second department manually to test the SelectList has multiple items
        _context.Departments.Add(new Department
        {
