    [Theory]
    [InlineData(".pdf")]
    [InlineData(".doc")]
    [InlineData(".txt")]
    [InlineData(".exe")]
    public void Create_POST_DisallowedExtensions_AddsModelError(string extension)
    {
        // Arrange
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 10000 + extension.GetHashCode(),
            Title = "Test Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        var mockFile = CreateMockFormFile($"file{extension}", 1024);

        // Act
        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        Assert.Empty(_context.Courses);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_POST_AllowedExtensions_DoesNotAddExtensionError(string extension)
    {
        // Arrange — valid extension but file I/O will fail (no real disk path)
        // This verifies the extension check passes and something else (file I/O) causes the error
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 20000 + Math.Abs(extension.GetHashCode()) % 9000,
            Title = "Test Valid Ext",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        var mockFile = CreateMockFormFile($"photo{extension}", 1024);

        // Act
        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        // Assert — if we get a ViewResult with error, it should NOT be the extension error
        Assert.NotNull(result);
        if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
        }
    }
}

