    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department SeedDepartment(string name = "Engineering", decimal budget = 100000m)
    {
        var instructor = new Instructor
        {
            LastName = "Fakhouri",
            FirstMidName = "Fadi",
            HireDate = new DateTime(2002, 7, 6)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var dept = new Department
        {
            Name = name,
            Budget = budget,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(Department dept, int courseId = 1050, string title = "Chemistry", int credits = 3)
    {
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
    {
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns(fileName);
        mockFile.Setup(f => f.Length).Returns(length);
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Verifiable();
        return mockFile;
    }

