4. namespace ContosoUniversity.Tests.Services;
5. 
6. public class NotificationServiceTests : IDisposable
7. {
8.     private readonly NotificationService _service;
9. 
10.     public NotificationServiceTests()
11.     {
12.         _service = new NotificationService();
13.         // Drain the static queue to isolate tests
14.         DrainQueue();
15.     }
16. 
17.     public void Dispose()
18.     {
19.         DrainQueue();
20.         _service.Dispose();
21.     }
22. 
23.     private void DrainQueue()
24.     {
25.         // ReceiveNotification dequeues from the static ConcurrentQueue
26.         while (_service.ReceiveNotification() != null) { }
27.     }
28. 
29.     [Fact]
30.     public void SendNotification_ValidParameters_CanBeReceived()
31.     {
32.         _service.SendNotification("Student", "42", EntityOperation.CREATE, "admin");
33. 
34.         var notification = _service.ReceiveNotification();
35. 
36.         Assert.NotNull(notification);
37.         Assert.Equal("Student", notification.EntityType);
38.         Assert.Equal("42", notification.EntityId);
39.         Assert.Equal("CREATE", notification.Operation);
40.         Assert.Equal("admin", notification.CreatedBy);
41.         Assert.False(notification.IsRead);
42.     }
43. 
44.     [Fact]
45.     public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
46.     {
47.         _service.SendNotification("Course", "101", "Calculus", EntityOperation.CREATE, "admin");
48. 
49.         var notification = _service.ReceiveNotification();
50. 
51.         Assert.NotNull(notification);
52.         Assert.Equal("New Course 'Calculus' has been created", notification.Message);
53.     }
54. 
55.     [Fact]
56.     public void SendNotification_WithoutDisplayName_UsesIdInMessage()
57.     {
58.         _service.SendNotification("Student", "7", EntityOperation.UPDATE, "teacher");
59. 
60.         var notification = _service.ReceiveNotification();
61. 
62.         Assert.NotNull(notification);
63.         Assert.Equal("Student (ID: 7) has been updated", notification.Message);
64.     }
65. 
66.     [Fact]
67.     public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
68.     {
69.         _service.SendNotification("Department", "5", "Math", EntityOperation.DELETE);
70. 
71.         var notification = _service.ReceiveNotification();
72. 
73.         Assert.NotNull(notification);
74.         Assert.Equal("Department 'Math' has been deleted", notification.Message);
75.     }
76. 
77.     [Fact]
78.     public void SendNotification_NullUserName_DefaultsToSystem()
79.     {
80.         _service.SendNotification("Course", "1", EntityOperation.CREATE);
81. 
82.         var notification = _service.ReceiveNotification();
83. 
84.         Assert.NotNull(notification);
85.         Assert.Equal("System", notification.CreatedBy);
86.     }
87. 
88.     [Fact]
89.     public void SendNotification_SetsCreatedAtToRecentTime()
90.     {
91.         var before = DateTime.Now.AddSeconds(-1);
92. 
93.         _service.SendNotification("Student", "1", EntityOperation.CREATE);
94. 
95.         var notification = _service.ReceiveNotification();
96.         Assert.NotNull(notification);
97.         Assert.True(notification.CreatedAt >= before);
98.         Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
99.     }
100. 
101.     [Fact]
102.     public void ReceiveNotification_EmptyQueue_ReturnsNull()
103.     {
104.         var result = _service.ReceiveNotification();
105. 
106.         Assert.Null(result);
107.     }
108. 
109.     [Fact]
110.     public void ReceiveNotification_MultipleEnqueued_ReturnsFIFOOrder()
111.     {
112.         _service.SendNotification("A", "1", EntityOperation.CREATE);
113.         _service.SendNotification("B", "2", EntityOperation.UPDATE);
114.         _service.SendNotification("C", "3", EntityOperation.DELETE);
115. 
116.         var first = _service.ReceiveNotification();
117.         var second = _service.ReceiveNotification();
118.         var third = _service.ReceiveNotification();
119.         var fourth = _service.ReceiveNotification();
