using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;
    private readonly NotificationService _drainService;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new InstructorsController(_context);
        _drainService = new NotificationService();
        DrainNotificationQueue();
    }

    public void Dispose()
    {
        DrainNotificationQueue();
        _controller.Dispose();
        _context.Dispose();
        _drainService.Dispose();
    }

    private void DrainNotificationQueue()
    {
        while (_drainService.ReceiveNotification() != null) { }
    }

    private Instructor SeedInstructor(string lastName = "Fakhouri", string firstName = "Fadi",
        DateTime? hireDate = null, string officeLocation = null)
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = hireDate ?? new DateTime(2002, 7, 6),
            CourseAssignments = new List<CourseAssignment>()
        };

        if (officeLocation != null)
        {
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = officeLocation
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();
            // Reload to attach the navigation
            _context.Entry(instructor).Reference(i => i.OfficeAssignment).Load();
            return instructor;
        }

        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", int? instructorId = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000m,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = instructorId
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int departmentId, int courseId = 1050, string title = "Chemistry", int credits = 3)
    {
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = departmentId,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    private void SeedCourseAssignment(int instructorId, int courseId)
    {
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructorId,
            CourseID = courseId
        });
        _context.SaveChanges();
    }

    // --- Index Tests ---

    [Fact]
    public void Index_ReturnsInstructorsWithOfficeAssignments()
    {
        var inst1 = SeedInstructor("Kapoor", "Candace", officeLocation: "Thompson 304");
        var inst2 = SeedInstructor("Harui", "Roger");

        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        var instructors = model.Instructors.ToList();
        Assert.Equal(2, instructors.Count);
        // Ordered by LastName: Harui first, then Kapoor
        Assert.Equal("Harui", instructors[0].LastName);
        Assert.Equal("Kapoor", instructors[1].LastName);
        Assert.NotNull(instructors[1].OfficeAssignment);
        Assert.Equal("Thompson 304", instructors[1].OfficeAssignment.Location);
        Assert.Null(instructors[0].OfficeAssignment);
    }

    [Fact]
    public void Index_WithSelectedInstructor_ShowsCourses()
    {
        var instructor = SeedInstructor("Abercrombie", "Kim");
        var dept = SeedDepartment("English", instructor.ID);
        var course1 = SeedCourse(dept.DepartmentID, 2021, "Composition");
        var course2 = SeedCourse(dept.DepartmentID, 2042, "Literature");
        SeedCourseAssignment(instructor.ID, course1.CourseID);
        SeedCourseAssignment(instructor.ID, course2.CourseID);

        var result = _controller.Index(instructor.ID, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        var courses = model.Courses.ToList();
        Assert.Equal(2, courses.Count);
        Assert.Contains(courses, c => c.Title == "Composition");
        Assert.Contains(courses, c => c.Title == "Literature");
    }

    [Fact]
    public void Index_WithSelectedCourse_ShowsEnrollments()
    {
        var instructor = SeedInstructor("Abercrombie", "Kim");
        var dept = SeedDepartment("English", instructor.ID);
        var course = SeedCourse(dept.DepartmentID, 2021, "Composition");
        SeedCourseAssignment(instructor.ID, course.CourseID);

        var student = new Student
        {
            LastName = "Li",
            FirstMidName = "Yan",
            EnrollmentDate = new DateTime(2012, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.B
        };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var result = _controller.Index(instructor.ID, course.CourseID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        var enrollments = model.Enrollments.ToList();
        Assert.Single(enrollments);
        Assert.Equal(Grade.B, enrollments[0].Grade);
        Assert.Equal(student.ID, enrollments[0].StudentID);
    }

    // --- Details Tests ---

    [Fact]
    public void Details_ValidId_ReturnsInstructor()
    {
        var instructor = SeedInstructor("Zheng", "Roger");

        var result = _controller.Details(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Zheng", model.LastName);
        Assert.Equal("Roger", model.FirstMidName);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    // --- Create Tests ---

    [Fact]
    public void Create_GET_ReturnsViewWithCourseCheckboxes()
    {
        var instructor = SeedInstructor();
        var dept = SeedDepartment("Math", instructor.ID);
        SeedCourse(dept.DepartmentID, 1045, "Calculus", 4);
        SeedCourse(dept.DepartmentID, 3141, "Trigonometry", 4);

        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);

        var courses = _controller.ViewBag.Courses as List<AssignedCourseData>;
        Assert.NotNull(courses);
        Assert.Equal(2, courses.Count);
        Assert.Contains(courses, c => c.Title == "Calculus" && !c.Assigned);
        Assert.Contains(courses, c => c.Title == "Trigonometry" && !c.Assigned);
    }

    [Fact]
    public void Create_POST_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            LastName = "NewInst",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 15),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);

        var saved = _context.Instructors.Single(i => i.LastName == "NewInst");
        Assert.Equal("Test", saved.FirstMidName);
        Assert.Equal(new DateTime(2020, 1, 15), saved.HireDate);
    }

    [Fact]
    public void Create_POST_WithCourseAssignments_SavesAssignments()
    {
        var existingInst = SeedInstructor();
        var dept = SeedDepartment("Math", existingInst.ID);
        var course1 = SeedCourse(dept.DepartmentID, 1045, "Calculus", 4);
        var course2 = SeedCourse(dept.DepartmentID, 3141, "Trigonometry", 4);

        var instructor = new Instructor
        {
            LastName = "WithCourses",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 3, 1)
        };

        var result = _controller.Create(instructor, new[] { course1.CourseID.ToString(), course2.CourseID.ToString() });

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);

        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .Single(i => i.LastName == "WithCourses");
        Assert.Equal(2, saved.CourseAssignments.Count);
        Assert.Contains(saved.CourseAssignments, ca => ca.CourseID == course1.CourseID);
        Assert.Contains(saved.CourseAssignments, ca => ca.CourseID == course2.CourseID);
    }

    [Fact]
    public void Create_POST_WithOfficeAssignment_SavesOffice()
    {
        var instructor = new Instructor
        {
            LastName = "WithOffice",
            FirstMidName = "Prof",
            HireDate = new DateTime(2019, 8, 15),
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" },
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);

        var saved = _context.Instructors
            .Include(i => i.OfficeAssignment)
            .Single(i => i.LastName == "WithOffice");
        Assert.NotNull(saved.OfficeAssignment);
        Assert.Equal("Room 101", saved.OfficeAssignment.Location);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        var existingInst = SeedInstructor();
        var dept = SeedDepartment("English", existingInst.ID);
        SeedCourse(dept.DepartmentID, 2021, "Composition");

        var instructor = new Instructor
        {
            LastName = "Invalid",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _controller.ModelState.AddModelError("HireDate", "Required");

        var result = _controller.Create(instructor, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Instructor>(viewResult.Model);
        // Should populate ViewBag.Courses even on invalid model
        var courses = _controller.ViewBag.Courses as List<AssignedCourseData>;
        Assert.NotNull(courses);
        Assert.Single(courses);
    }

    // --- Edit GET Tests ---

    [Fact]
    public void Edit_GET_ValidId_ReturnsInstructorWithCourses()
    {
        var instructor = SeedInstructor("Harui", "Roger");
        var dept = SeedDepartment("Engineering", instructor.ID);
        var course = SeedCourse(dept.DepartmentID, 1050, "Chemistry");
        SeedCourseAssignment(instructor.ID, course.CourseID);

        var result = _controller.Edit(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Harui", model.LastName);
        Assert.Single(model.CourseAssignments);

        var courses = _controller.ViewBag.Courses as List<AssignedCourseData>;
        Assert.NotNull(courses);
        Assert.Single(courses);
        Assert.True(courses[0].Assigned);
        Assert.Equal("Chemistry", courses[0].Title);
    }

    [Fact]
    public void Edit_GET_InvalidId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    // --- Delete Tests ---

    [Fact]
    public void Delete_GET_ValidId_ReturnsInstructor()
    {
        var instructor = SeedInstructor("Kapoor", "Candace");

        var result = _controller.Delete(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Kapoor", model.LastName);
        Assert.Equal("Candace", model.FirstMidName);
    }

    [Fact]
    public void Delete_GET_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
    {
        var instructor = SeedInstructor("ToDelete", "Test");

        var result = _controller.DeleteConfirmed(instructor.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Instructors.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_InstructorWithOffice_RemovesBoth()
    {
        var instructor = SeedInstructor("WithOffice", "Del", officeLocation: "Room 505");

        var result = _controller.DeleteConfirmed(instructor.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Instructors.Find(instructor.ID));
        Assert.Null(_context.OfficeAssignments.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDeptAdmin_NullsDepartmentInstructorId()
    {
        var instructor = SeedInstructor("DeptHead", "Admin");
        var dept = SeedDepartment("Economics", instructor.ID);

        _controller.DeleteConfirmed(instructor.ID);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.NotNull(updatedDept);
        Assert.Null(updatedDept.InstructorID);
    }

    [Fact]
    public void Create_POST_ValidInstructor_SendsNotification()
    {
        DrainNotificationQueue();

        var instructor = new Instructor
        {
            LastName = "Notified",
            FirstMidName = "Create",
            HireDate = new DateTime(2020, 5, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, null);

        var notification = _drainService.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("CREATE", notification.Operation);
    }

    [Fact]
    public void DeleteConfirmed_SendsDeleteNotification()
    {
        var instructor = SeedInstructor("NotifyDel", "Test");
        DrainNotificationQueue();

        _controller.DeleteConfirmed(instructor.ID);

        var notification = _drainService.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Equal(instructor.ID.ToString(), notification.EntityId);
    }
}

using System;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;
    private readonly NotificationService _helperService;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _helperService = new NotificationService();
        DrainQueue();
        _controller = new NotificationsController(_context);
    }

    public void Dispose()
    {
        DrainQueue();
        _controller.Dispose();
        _context.Dispose();
        _helperService.Dispose();
    }

    private void DrainQueue()
    {
        while (_helperService.ReceiveNotification() != null) { }
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
    {
        DrainQueue();

        var result = _controller.GetNotifications();

        Assert.IsType<JsonResult>(result);
        dynamic data = result.Value!;
        var type = data.GetType();
        var success = (bool)type.GetProperty("success")!.GetValue(data);
        var count = (int)type.GetProperty("count")!.GetValue(data);
        Assert.True(success);
        Assert.Equal(0, count);
    }

    [Fact]
    public void GetNotifications_WithQueuedItems_ReturnsNotifications()
    {
        // Enqueue via a separate service instance (same static queue)
        _helperService.SendNotification("Student", "1", EntityOperation.CREATE, "admin");
        _helperService.SendNotification("Course", "101", EntityOperation.UPDATE, "admin");

        var result = _controller.GetNotifications();

        Assert.IsType<JsonResult>(result);
        dynamic data = result.Value!;
        var type = data.GetType();
        var success = (bool)type.GetProperty("success")!.GetValue(data);
        var count = (int)type.GetProperty("count")!.GetValue(data);
        Assert.True(success);
        Assert.Equal(2, count);
    }

    [Fact]
    public void GetNotifications_LimitsToTenItems()
    {
        for (int i = 0; i < 15; i++)
        {
            _helperService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "test");
        }

        var result = _controller.GetNotifications();

        dynamic data = result.Value!;
        var type = data.GetType();
        var count = (int)type.GetProperty("count")!.GetValue(data);
        Assert.Equal(10, count);
    }

    [Fact]
    public void GetNotifications_DrainsFromQueue_SubsequentCallReturnsRemaining()
    {
        for (int i = 0; i < 12; i++)
        {
            _helperService.SendNotification("Item", i.ToString(), EntityOperation.CREATE, "user");
        }

        // First call takes up to 10
        var result1 = _controller.GetNotifications();
        dynamic data1 = result1.Value!;
        var count1 = (int)data1.GetType().GetProperty("count")!.GetValue(data1);
        Assert.Equal(10, count1);

        // Second call gets remaining 2
        var result2 = _controller.GetNotifications();
        dynamic data2 = result2.Value!;
        var count2 = (int)data2.GetType().GetProperty("count")!.GetValue(data2);
        Assert.Equal(2, count2);
    }

    [Fact]
    public void MarkAsRead_ValidId_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(42);

        Assert.IsType<JsonResult>(result);
        dynamic data = result.Value!;
        var type = data.GetType();
        var success = (bool)type.GetProperty("success")!.GetValue(data);
        Assert.True(success);
    }

    [Fact]
    public void MarkAsRead_InvalidId_StillReturnsSuccess()
    {
        // MarkAsRead is a no-op for in-memory impl, so even invalid ID succeeds
        var result = _controller.MarkAsRead(-1);

        Assert.IsType<JsonResult>(result);
        dynamic data = result.Value!;
        var type = data.GetType();
        var success = (bool)type.GetProperty("success")!.GetValue(data);
        Assert.True(success);
    }
}

