    [Fact]
    public void OnModelCreating_CourseAssignmentHasCompositeKey()
    {
        // CourseAssignment uses composite key {CourseID, InstructorID}
        var instructor = new Instructor
        {
            LastName = "Key",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 1)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var dept = new Department
        {
            Name = "KeyDept",
            Budget = 10000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 7777,
            Title = "KeyCourse",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var assignment = new CourseAssignment
        {
            CourseID = course.CourseID,
            InstructorID = instructor.ID
        };
        _context.CourseAssignments.Add(assignment);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments
            .Single(ca => ca.CourseID == course.CourseID && ca.InstructorID == instructor.ID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }

    [Fact]
    public void OnModelCreating_CourseHasNoDatabaseGeneratedKey()
    {
        // Course uses DatabaseGeneratedOption.None — CourseID is user-provided
        var dept = new Department
        {
            Name = "NogenDept",
            Budget = 10000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 5555,
            Title = "ExplicitId",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Find(5555);
        Assert.NotNull(retrieved);
        Assert.Equal(5555, retrieved!.CourseID);
        Assert.Equal("ExplicitId", retrieved.Title);
    }

    [Fact]
    public void SchoolContext_OfficeAssignmentOneToOneWithInstructor()
    {
