    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new InstructorsController(_context);
        _drainService = new NotificationService();
        DrainNotificationQueue();
    }

    public void Dispose()
    {
        DrainNotificationQueue();
        _controller.Dispose();
        _context.Dispose();
        _drainService.Dispose();
    }

    private void DrainNotificationQueue()
    {
        while (_drainService.ReceiveNotification() != null) { }
    }

    private Instructor SeedInstructor(string lastName = "Fakhouri", string firstName = "Fadi",
        DateTime? hireDate = null, string officeLocation = null)
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = hireDate ?? new DateTime(2002, 7, 6),
            CourseAssignments = new List<CourseAssignment>()
        };

        if (officeLocation != null)
        {
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = officeLocation
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();
            // Reload to attach the navigation
            _context.Entry(instructor).Reference(i => i.OfficeAssignment).Load();
            return instructor;
        }

        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", int? instructorId = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000m,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = instructorId
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int departmentId, int courseId = 1050, string title = "Chemistry", int credits = 3)
    {
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = departmentId,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    private void SeedCourseAssignment(int instructorId, int courseId)
    {
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructorId,
            CourseID = courseId
        });
        _context.SaveChanges();
    }

