    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        DbInitializer.Initialize(_context);

        var students = _context.Students.ToList();
        Assert.Equal(8, students.Count);
        Assert.Contains(students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        DbInitializer.Initialize(_context);

        var courses = _context.Courses.ToList();
        Assert.Equal(7, courses.Count);
        Assert.Contains(courses, c => c.Title == "Chemistry" && c.CourseID == 1050 && c.Credits == 3);
        Assert.Contains(courses, c => c.Title == "Calculus" && c.CourseID == 1045 && c.Credits == 4);
        Assert.Contains(courses, c => c.Title == "Literature" && c.CourseID == 2042);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        DbInitializer.Initialize(_context);

        var instructors = _context.Instructors.ToList();
        Assert.Equal(5, instructors.Count);
        Assert.Contains(instructors, i => i.LastName == "Abercrombie" && i.FirstMidName == "Kim");
        Assert.Contains(instructors, i => i.LastName == "Zheng" && i.FirstMidName == "Roger");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        DbInitializer.Initialize(_context);

        var departments = _context.Departments.ToList();
        Assert.Equal(4, departments.Count);
        Assert.Contains(departments, d => d.Name == "English" && d.Budget == 350000m);
        Assert.Contains(departments, d => d.Name == "Mathematics" && d.Budget == 100000m);
        Assert.Contains(departments, d => d.Name == "Engineering");
        Assert.Contains(departments, d => d.Name == "Economics");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        DbInitializer.Initialize(_context);

        var enrollments = _context.Enrollments.ToList();
        Assert.Equal(11, enrollments.Count);
        // Alexander has 3 enrollments
        var alexanderId = _context.Students.Single(s => s.LastName == "Alexander").ID;
        Assert.Equal(3, enrollments.Count(e => e.StudentID == alexanderId));
        // Verify specific grade
        var chemCourseId = _context.Courses.Single(c => c.Title == "Chemistry").CourseID;
        var alexanderChem = enrollments.Single(e => e.StudentID == alexanderId && e.CourseID == chemCourseId);
        Assert.Equal(Grade.A, alexanderChem.Grade);
    }

    [Fact]
    public void Initialize_PreSeededDatabase_DoesNotDuplicate()
    {
        // Seed once
        DbInitializer.Initialize(_context);
        var studentCountFirst = _context.Students.Count();
        var courseCountFirst = _context.Courses.Count();

        // Seed again - should be a no-op
        DbInitializer.Initialize(_context);

        Assert.Equal(studentCountFirst, _context.Students.Count());
        Assert.Equal(courseCountFirst, _context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsCorrectNumberOfStudents()
    {
        DbInitializer.Initialize(_context);

        // Verify exact count and each student's enrollment date is set
        var students = _context.Students.ToList();
        Assert.Equal(8, students.Count);
        Assert.All(students, s =>
        {
            Assert.False(string.IsNullOrWhiteSpace(s.LastName));
            Assert.False(string.IsNullOrWhiteSpace(s.FirstMidName));
            Assert.NotEqual(default, s.EnrollmentDate);
        });
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        DbInitializer.Initialize(_context);

        var offices = _context.OfficeAssignments.ToList();
        Assert.Equal(3, offices.Count);
        Assert.Contains(offices, o => o.Location == "Smith 17");
        Assert.Contains(offices, o => o.Location == "Gowan 27");
        Assert.Contains(offices, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        DbInitializer.Initialize(_context);

        var assignments = _context.CourseAssignments.ToList();
        Assert.Equal(8, assignments.Count);

        // Abercrombie teaches Composition and Literature
        var abercrombie = _context.Instructors.Single(i => i.LastName == "Abercrombie");
        var abercrombieCourses = assignments.Where(a => a.InstructorID == abercrombie.ID).ToList();
        Assert.Equal(2, abercrombieCourses.Count);
    }

    [Fact]
    public void Initialize_DepartmentsHaveCorrectAdministrators()
    {
        DbInitializer.Initialize(_context);

        var english = _context.Departments.Single(d => d.Name == "English");
        var abercrombie = _context.Instructors.Single(i => i.LastName == "Abercrombie");
        Assert.Equal(abercrombie.ID, english.InstructorID);

        var math = _context.Departments.Single(d => d.Name == "Mathematics");
        var fakhouri = _context.Instructors.Single(i => i.LastName == "Fakhouri");
        Assert.Equal(fakhouri.ID, math.InstructorID);
    }
}

