using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests : IDisposable
{
    private readonly SchoolContext _context;

    public DbInitializerTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        DbInitializer.Initialize(_context);

        var students = _context.Students.ToList();
        Assert.Equal(8, students.Count);
        Assert.Contains(students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        DbInitializer.Initialize(_context);

        var courses = _context.Courses.ToList();
        Assert.Equal(7, courses.Count);
        Assert.Contains(courses, c => c.Title == "Chemistry" && c.CourseID == 1050 && c.Credits == 3);
        Assert.Contains(courses, c => c.Title == "Calculus" && c.CourseID == 1045 && c.Credits == 4);
        Assert.Contains(courses, c => c.Title == "Literature" && c.CourseID == 2042);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        DbInitializer.Initialize(_context);

        var instructors = _context.Instructors.ToList();
        Assert.Equal(5, instructors.Count);
        Assert.Contains(instructors, i => i.LastName == "Abercrombie" && i.FirstMidName == "Kim");
        Assert.Contains(instructors, i => i.LastName == "Zheng" && i.FirstMidName == "Roger");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        DbInitializer.Initialize(_context);

        var departments = _context.Departments.ToList();
        Assert.Equal(4, departments.Count);
        Assert.Contains(departments, d => d.Name == "English" && d.Budget == 350000m);
        Assert.Contains(departments, d => d.Name == "Mathematics" && d.Budget == 100000m);
        Assert.Contains(departments, d => d.Name == "Engineering");
        Assert.Contains(departments, d => d.Name == "Economics");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        DbInitializer.Initialize(_context);

        var enrollments = _context.Enrollments.ToList();
        Assert.Equal(11, enrollments.Count);
        // Alexander has 3 enrollments
        var alexanderId = _context.Students.Single(s => s.LastName == "Alexander").ID;
        Assert.Equal(3, enrollments.Count(e => e.StudentID == alexanderId));
        // Verify specific grade
        var chemCourseId = _context.Courses.Single(c => c.Title == "Chemistry").CourseID;
        var alexanderChem = enrollments.Single(e => e.StudentID == alexanderId && e.CourseID == chemCourseId);
        Assert.Equal(Grade.A, alexanderChem.Grade);
    }

    [Fact]
    public void Initialize_PreSeededDatabase_DoesNotDuplicate()
    {
        // Seed once
        DbInitializer.Initialize(_context);
        var studentCountFirst = _context.Students.Count();
        var courseCountFirst = _context.Courses.Count();

        // Seed again - should be a no-op
        DbInitializer.Initialize(_context);

        Assert.Equal(studentCountFirst, _context.Students.Count());
        Assert.Equal(courseCountFirst, _context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsCorrectNumberOfStudents()
    {
        DbInitializer.Initialize(_context);

        // Verify exact count and each student's enrollment date is set
        var students = _context.Students.ToList();
        Assert.Equal(8, students.Count);
        Assert.All(students, s =>
        {
            Assert.False(string.IsNullOrWhiteSpace(s.LastName));
            Assert.False(string.IsNullOrWhiteSpace(s.FirstMidName));
            Assert.NotEqual(default, s.EnrollmentDate);
        });
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        DbInitializer.Initialize(_context);

        var offices = _context.OfficeAssignments.ToList();
        Assert.Equal(3, offices.Count);
        Assert.Contains(offices, o => o.Location == "Smith 17");
        Assert.Contains(offices, o => o.Location == "Gowan 27");
        Assert.Contains(offices, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        DbInitializer.Initialize(_context);

        var assignments = _context.CourseAssignments.ToList();
        Assert.Equal(8, assignments.Count);

        // Abercrombie teaches Composition and Literature
        var abercrombie = _context.Instructors.Single(i => i.LastName == "Abercrombie");
        var abercrombieCourses = assignments.Where(a => a.InstructorID == abercrombie.ID).ToList();
        Assert.Equal(2, abercrombieCourses.Count);
    }

    [Fact]
    public void Initialize_DepartmentsHaveCorrectAdministrators()
    {
        DbInitializer.Initialize(_context);

        var english = _context.Departments.Single(d => d.Name == "English");
        var abercrombie = _context.Instructors.Single(i => i.LastName == "Abercrombie");
        Assert.Equal(abercrombie.ID, english.InstructorID);

        var math = _context.Departments.Single(d => d.Name == "Mathematics");
        var fakhouri = _context.Instructors.Single(i => i.LastName == "Fakhouri");
        Assert.Equal(fakhouri.ID, math.InstructorID);
    }
}

using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void SchoolContext_HasStudentsDbSet()
    {
        Assert.NotNull(_context.Students);
        // Verify it's queryable (empty at start)
        Assert.Empty(_context.Students.ToList());
    }

    [Fact]
    public void SchoolContext_HasCoursesDbSet()
    {
        Assert.NotNull(_context.Courses);
        Assert.Empty(_context.Courses.ToList());
    }

    [Fact]
    public void SchoolContext_HasDepartmentsDbSet()
    {
        Assert.NotNull(_context.Departments);
        Assert.Empty(_context.Departments.ToList());
    }

    [Fact]
    public void SchoolContext_HasInstructorsDbSet()
    {
        Assert.NotNull(_context.Instructors);
        Assert.Empty(_context.Instructors.ToList());
    }

    [Fact]
    public void SchoolContext_HasEnrollmentsDbSet()
    {
        Assert.NotNull(_context.Enrollments);
        Assert.Empty(_context.Enrollments.ToList());
    }

    [Fact]
    public void SchoolContext_HasNotificationsDbSet()
    {
        Assert.NotNull(_context.Notifications);
        Assert.Empty(_context.Notifications.ToList());
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            LastName = "TestLast",
            FirstMidName = "TestFirst",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.Single(s => s.LastName == "TestLast");
        Assert.Equal("TestFirst", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
        Assert.True(retrieved.ID > 0);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveCourse()
    {
        var dept = new Department
        {
            Name = "TestDept",
            Budget = 50000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 9999,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Single(c => c.CourseID == 9999);
        Assert.Equal("Test Course", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
        Assert.Equal(dept.DepartmentID, retrieved.DepartmentID);
    }

    [Fact]
    public void OnModelCreating_CourseAssignmentHasCompositeKey()
    {
        // CourseAssignment uses composite key {CourseID, InstructorID}
        var instructor = new Instructor
        {
            LastName = "Key",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 1)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var dept = new Department
        {
            Name = "KeyDept",
            Budget = 10000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 7777,
            Title = "KeyCourse",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var assignment = new CourseAssignment
        {
            CourseID = course.CourseID,
            InstructorID = instructor.ID
        };
        _context.CourseAssignments.Add(assignment);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments
            .Single(ca => ca.CourseID == course.CourseID && ca.InstructorID == instructor.ID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }

    [Fact]
    public void OnModelCreating_CourseHasNoDatabaseGeneratedKey()
    {
        // Course uses DatabaseGeneratedOption.None — CourseID is user-provided
        var dept = new Department
        {
            Name = "NogenDept",
            Budget = 10000m,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 5555,
            Title = "ExplicitId",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Find(5555);
        Assert.NotNull(retrieved);
        Assert.Equal(5555, retrieved!.CourseID);
        Assert.Equal("ExplicitId", retrieved.Title);
    }

    [Fact]
    public void SchoolContext_OfficeAssignmentOneToOneWithInstructor()
    {
        var instructor = new Instructor
        {
            LastName = "OfficeTester",
            FirstMidName = "One",
            HireDate = new DateTime(2020, 1, 1)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var office = new OfficeAssignment
        {
            InstructorID = instructor.ID,
            Location = "Building A Room 1"
        };
        _context.OfficeAssignments.Add(office);
        _context.SaveChanges();

        var retrieved = _context.OfficeAssignments.Find(instructor.ID);
        Assert.NotNull(retrieved);
        Assert.Equal("Building A Room 1", retrieved!.Location);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }
}

