         var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

         Assert.Equal(3, result.Count);
         Assert.Equal(4, result[0]); // items 4,5,6
         Assert.Equal(5, result[1]);
         Assert.Equal(6, result[2]);
         Assert.True(result.HasPreviousPage);
         Assert.True(result.HasNextPage);
     }

     [Fact]
     public void Create_EmptySource_ReturnsEmptyList()
     {
         var source = Enumerable.Empty<int>().AsQueryable();

         var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

         Assert.Empty(result);
         Assert.Equal(1, result.PageIndex);
         Assert.Equal(0, result.TotalPages);
         Assert.False(result.HasPreviousPage);
         Assert.False(result.HasNextPage);
     }

     [Fact]
     public void Create_PageSizeLargerThanSource_ReturnsSinglePage()
     {
         var source = CreateSource(5);

         var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 50);

         Assert.Equal(5, result.Count);
         Assert.Equal(1, result.TotalPages);
         Assert.False(result.HasPreviousPage);
         Assert.False(result.HasNextPage);
         // Verify actual items are correct (not just count)
         Assert.Equal(1, result[0]);
         Assert.Equal(5, result[4]);
     }

     [Fact]
     public void Create_PageIndexBeyondRange_ReturnsEmptyList()
     {
         var source = CreateSource(5);

         // 5 items, page size 3 => 2 pages; page 5 is beyond
         var result = PaginatedList<int>.Create(source, pageIndex: 5, pageSize: 3);

         Assert.Empty(result);
         Assert.Equal(5, result.PageIndex);
         Assert.Equal(2, result.TotalPages);
         Assert.True(result.HasPreviousPage); // 5 > 1
         Assert.False(result.HasNextPage);    // 5 >= 2
     }

     [Theory]
     [InlineData(10, 3, 4)]  // ceil(10/3) = 4
     [InlineData(9, 3, 3)]   // exact division
     [InlineData(1, 3, 1)]   // single item
     [InlineData(7, 5, 2)]   // ceil(7/5) = 2
     public void Create_TotalPages_CalculatesCorrectly(int itemCount, int pageSize, int expectedTotalPages)
     {
         var source = CreateSource(itemCount);

         var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: pageSize);

         Assert.Equal(expectedTotalPages, result.TotalPages);
     }

     [Fact]
     public void Create_SecondPage_SkipsFirstPageItems()
     {
         // Verify Skip/Take logic: page 2 with size 4 should skip 4 items
         var source = CreateSource(12);

         var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 4);

         Assert.Equal(4, result.Count);
         Assert.Equal(5, result[0]);  // first skipped item + 1
         Assert.Equal(8, result[3]);  // last item on page 2
         Assert.Equal(2, result.PageIndex);
     }

     [Fact]
     public void Constructor_SetsPropertiesCorrectly()
     {
         var items = new List<string> { "alpha", "beta" };

         var list = new PaginatedList<string>(items, count: 10, pageIndex: 3, pageSize: 2);

         Assert.Equal(3, list.PageIndex);
         Assert.Equal(5, list.TotalPages); // ceil(10/2) = 5
         Assert.Equal(2, list.Count);
         Assert.Equal("alpha", list[0]);
         Assert.Equal("beta", list[1]);
         Assert.True(list.HasPreviousPage);
         Assert.True(list.HasNextPage);
     }

     [Fact]
     public void HasPreviousPage_PageIndex1_ReturnsFalse()
     {
         var list = new PaginatedList<int>(new List<int> { 1 }, count: 5, pageIndex: 1, pageSize: 1);

         Assert.False(list.HasPreviousPage);
     }

     [Fact]
     public void HasNextPage_OnLastPage_ReturnsFalse()
     {
         // TotalPages = ceil(5/1) = 5, pageIndex = 5
         var list = new PaginatedList<int>(new List<int> { 5 }, count: 5, pageIndex: 5, pageSize: 1);

         Assert.False(list.HasNextPage);
         Assert.True(list.HasPreviousPage);
     }
