    [Fact]
    public void Index_SortByDateDesc_ReturnsSortedByEnrollmentDateDescending()
    {
        // Arrange — seed students with distinct enrollment dates
        using var context = TestDbContextFactory.Create();
        SeedStudents(context);
        using var controller = new StudentsController(context);

        // Act
        var result = controller.Index("date_desc", null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(5, model.Count);
        // Descending by EnrollmentDate: Justice (2022), Alonso (2021), Alexander/Li (2020), Barzdukas (2019)
        Assert.Equal("Justice", model[0].LastName);
        Assert.Equal(new DateTime(2022, 9, 1), model[0].EnrollmentDate);
        Assert.Equal("Barzdukas", model[4].LastName);
        Assert.Equal(new DateTime(2019, 9, 1), model[4].EnrollmentDate);
        // Verify descending ordering across all elements
        for (int i = 0; i < model.Count - 1; i++)
        {
            Assert.True(model[i].EnrollmentDate >= model[i + 1].EnrollmentDate,
                $"Expected {model[i].LastName} ({model[i].EnrollmentDate:d}) >= {model[i + 1].LastName} ({model[i + 1].EnrollmentDate:d})");
        }
    }

