    [Fact]
    public void DeleteConfirmed_SendsDeleteNotification()
    {
        var instructor = SeedInstructor("NotifyDel", "Test");
        DrainNotificationQueue();

        _controller.DeleteConfirmed(instructor.ID);

        var notification = _drainService.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Equal(instructor.ID.ToString(), notification.EntityId);
    }

    // ---- Gap: Create POST with null selectedCourses ----

    [Fact]
    public void Create_POST_NullSelectedCourses_SavesInstructorWithNoCourseAssignments()
    {
        // Arrange — seed some courses to confirm they are NOT assigned
        var existingInst = SeedInstructor();
        var dept = SeedDepartment("Science", existingInst.ID);
        var course1 = SeedCourse(dept.DepartmentID, 5050, "Physics", 4);
        var course2 = SeedCourse(dept.DepartmentID, 5051, "Biology", 3);

        var instructor = new Instructor
        {
            LastName = "NoCourses",
            FirstMidName = "None",
            HireDate = new DateTime(2021, 6, 1)
        };

        // Act — pass null for selectedCourses
        var result = _controller.Create(instructor, null);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);

        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .Single(i => i.LastName == "NoCourses");
        Assert.Equal("None", saved.FirstMidName);
        Assert.Equal(new DateTime(2021, 6, 1), saved.HireDate);
        // The key assertion: no course assignments when selectedCourses is null
        Assert.NotNull(saved.CourseAssignments);
        Assert.Empty(saved.CourseAssignments);
        // Verify the existing courses are unaffected (no spurious assignments)
        Assert.Equal(2, _context.Courses.Count());
        Assert.Empty(_context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID));
    }
}

